-- Removes Berean Standard Bible section headings that were imported into the
-- text of the verse preceding them.
--
-- The USFM parser split only on \c and \v markers, so heading lines (\s1 and
-- friends) between verses were absorbed by the verse before. src/Bible/UsfmPackage.php
-- now strips them, and this file corrects the rows already in the database.
--
-- Safe to run more than once: each statement matches on the exact damaged text,
-- so a row already corrected is left alone. Nothing here deletes a verse.
--
-- Verses corrected: 1919

SET @translation := (SELECT id FROM translations WHERE code = 'BSB');


SET @book := (SELECT id FROM books WHERE code = '1CH');
UPDATE bible_verses SET text = 'and Abram (that is, Abraham).' WHERE translation_id = @translation AND book_id = @book AND chapter = 1 AND verse = 27 AND verse_suffix = '' AND text = 'and Abram (that is, Abraham). The Descendants of Abraham (Genesis 25:12–18)';
